class EpisodePanel extends CommonSlidePage {
  const EpisodePanel({
    super.key,
    super.enableSlide,
    this.onReverse,
    required this.type,
    this.episodeType,
    required this.isSidePanel,
    required this.introController,
  });

  final EpisodeType type;
  final PgcEpisodeType? episodeType;
  final bool isSidePanel;
  final VoidCallback? onReverse;
  final CommonIntroController introController;

  @override
  State<EpisodePanel> createState() => _EpisodePanelState();
}

class _EpisodePanelState extends State<EpisodePanel>
    with TickerProviderStateMixin, CommonSlideMixin {
  ColorScheme get colorScheme => theme.colorScheme;
  late final _type = widget.type;
  late final _isSidePanel = widget.isSidePanel;
  late final _introController = widget.introController;

  // ugc
  late final bool _isUgc;
  TabController? _tabController;
  late final _hasSections = _tabController != null;
  late List<SectionItem> _sections;
  late VideoDetailData _videoDetail;
  PgcEpisodeType get _episodeType =>
      widget.episodeType ?? _pgcController.episodeType;
  List<ugc.BaseEpisodeItem> get _pgcEpisodes =>
      _isSidePanel || _episodeType == .episode
      ? _pgcItem.episodes!
      : _pgcItem.sections![_pgcController.sectionIndex].episodes!;
  late final _ugcController = _introController as UgcIntroController;

  // pgc
  late PgcInfoModel _pgcItem;
  late final _pgcController = _introController as PgcIntroController;

  // fav
  late final int _seasonId;
  RxnBool? _favState;

  // reverse
  late final _rxTabIndex = Rx(_tabIndex());
  late bool _reverse;
  late final List<bool> _reverseList;

  bool _isReversed(int tabIndex) {
    if (_hasSections) {
      return _reverseList[tabIndex];
    }
    return _reverse;
  }

  void _setReverse(int tabIndex, bool value) {
    if (_hasSections) {
      _reverseList[tabIndex] = value;
    }
    _reverse = value;
  }

  void _tabListener() {
    _rxTabIndex.value = _tabController!.index;
  }

  late int _lastTabIndex;
  late int _lastItemIndex;
  late final int Function() _tabIndex;
  late final int Function() _itemIndex;
  late List<ugc.BaseEpisodeItem> _episodes;

  final _scrollController = ScrollController();
  late final List<int?> _posList;

  int _posIndex(int tabIndex) {
    return _posList[tabIndex]!;
  }

  void setPosIndex(int tabIndex) {
    _posList[tabIndex] ??= _scrollController.positions.length;
  }

  void _addUgcListener() {
    _ugcController.indexNotifier.addListener(_refresh);
  }

  void _removeUgcListener() {
    _ugcController.indexNotifier.removeListener(_refresh);
  }

  void _refresh([_]) {
    if (!mounted) return;

    final tabIndex = _tabIndex();
    final tabIndexChanged = _lastTabIndex != tabIndex;
    _lastTabIndex = tabIndex;

    final itemIndex = _itemIndex();
    final itemIndexChanged = _lastItemIndex != itemIndex;
    _lastItemIndex = itemIndex;

    _syncEpisodes(tabIndex);

    setState(() {});

    if (tabIndexChanged || itemIndexChanged) {
      _jumpToCurrent();
    }
  }

  void _syncEpisodes(int tabIndex) {
    switch (_type) {
      case .part:
        _videoDetail = _ugcController.videoDetail.rawValue;
        _episodes = _videoDetail.pages!;
      case .season:
        _videoDetail = _ugcController.videoDetail.rawValue;
        _sections = _videoDetail.ugcSeason!.sections!;
        _episodes = _sections[tabIndex].episodes!;
      case .pgc:
        _pgcItem = _pgcController.pgcItem;
        _episodes = _pgcEpisodes;
    }
  }

  StreamSubscription? _pgcListener;

  void _addPgcListener() {
    _pgcListener = _pgcController.cid.listen(_onCidChanged);
  }

  void _removePgcListener() {
    _pgcListener?.cancel();
    _pgcListener = null;
  }

  void _onCidChanged([_]) {
    WidgetsBinding.instance.addPostFrameCallback(_refresh);
  }

  @override
  void initState() {
    super.initState();
    switch (_type) {
      case .part:
        _isUgc = true;
        _reverse = false;
        _tabIndex = () => 0;
        _itemIndex = () => _ugcController.partIndex;
        _videoDetail = _ugcController.videoDetail.rawValue;
        _episodes = _videoDetail.pages!;
        _addUgcListener();

      case .season:
        _isUgc = true;
        _tabIndex = () => _ugcController.sectionIndex;
        _itemIndex = () => _ugcController.seasonIndex;
        _videoDetail = _ugcController.videoDetail.rawValue;
        _sections = _videoDetail.ugcSeason!.sections!;
        if (_sections.length > 1) {
          _tabController = TabController(
            vsync: this,
            length: _sections.length,
            initialIndex: _ugcController.sectionIndex,
          )..addListener(_tabListener);
          _episodes = _sections[_tabIndex()].episodes!;
          _reverseList = List.filled(_sections.length, false);
          _posList = List.filled(_sections.length, null);
        } else {
          _reverse = false;
          _episodes = _sections.first.episodes!;
        }
        _addUgcListener();

        if (Accounts.main.isLogin) {
          _seasonId = _videoDetail.seasonId!;
          final favState = _ugcController.seasonFavState[_seasonId];
          if (favState != null) {
            _favState = RxnBool(favState);
          } else {
            _favState = RxnBool(null);
            VideoHttp.videoRelation(bvid: _ugcController.bvid).then(
              (result) {
                if (!mounted) return;
                if (result case Success(:final response)) {
                  final seasonFav = response.seasonFav ?? false;
                  _favState!.value = seasonFav;
                  _ugcController.seasonFavState[_seasonId] = seasonFav;
                }
              },
            );
          }
        }

      case .pgc:
        _isUgc = false;
        _reverse = false;
        _tabIndex = () => _pgcController.seasonIndex;
        _itemIndex = _isSidePanel
            ? () => _pgcController.episodeIndex
            : () => _episodeType == .episode
                  ? _pgcController.episodeIndex
                  : _pgcController.pvIndex;
        _pgcItem = _pgcController.pgcItem;
        _episodes = _pgcEpisodes;
        _addPgcListener();
    }

    _lastTabIndex = _tabIndex();
    _lastItemIndex = _itemIndex();
    if (_lastItemIndex > 0) {
      WidgetsBinding.instance.addPostFrameCallback(
        (_) => _jumpToIndex(index: _lastItemIndex),
      );
    }
  }

  void _jumpToTop() => _jumpToIndex(top: true);

  void _jumpToBottom() => _jumpToIndex(top: false);

  Future<void> _jumpToCurrent() async {
    final itemIndex = _itemIndex();
    if (itemIndex == -1) return; // pgc

    if (_hasSections) {
      final tabIndex = _tabIndex();
      if (_tabController!.index != tabIndex) {
        _tabController!.animateTo(tabIndex);
        await Future.pause(const Duration(milliseconds: 225));
        if (!mounted) return;
      }
    }

    _jumpToIndex(index: itemIndex);
  }

  void _jumpToIndex({int? index, bool? top}) {
    if (!_scrollController.hasClients) {
      if (kDebugMode) assert(false);
      return;
    }

    int itemIndex;
    final int tabIndex;
    final List<ugc.BaseEpisodeItem> episodes;
    if (_hasSections) {
      tabIndex = _tabController!.index;
      episodes = _sections[tabIndex].episodes!;
    } else {
      tabIndex = 0;
      episodes = _episodes;
    }
    final isReversed = _isReversed(tabIndex);
    itemIndex = index ?? (top! ^ isReversed ? 0 : episodes.length - 1);

    final (double height, double offset, double remain) = calcItemOffset(
      index: itemIndex,
      episodes: episodes,
      isReversed: isReversed,
    );

    final position = _hasSections
        ? _scrollController.positions.elementAt(_posIndex(tabIndex))
        : _scrollController.position;
    final adjustOffset = adjustScrollOffset(
      extent: height,
      offset: offset,
      remain: remain,
      viewportDimension: position.viewportDimension,
      isReversed: isReversed,
    );
    position.jumpTo(adjustOffset);
  }

  @override
  void dispose() {
    _tabController
      ?..removeListener(_tabListener)
      ..dispose();
    _tabController = null;
    _removeListener();
    _scrollController.dispose();
    super.dispose();
  }

  void _removeListener() {
    if (_isUgc) {
      _removeUgcListener();
    } else {
      _removePgcListener();
    }
  }

  bool _popIfNeeded() {
    if (_isSidePanel) return false;
    _pop();
    return true;
  }

  void _pop() {
    _removeListener();
    Get.back();
  }

  @override
  Widget buildPage() {
    final child = Column(
      children: [
        _buildToolbar(),
        if (_hasSections)
          TabBar(
            dividerHeight: 1,
            isScrollable: true,
            controller: _tabController,
            padding: const .only(right: 60),
            tabs: _sections.map((e) => Tab(text: e.title)).toList(),
            dividerColor: colorScheme.outline.withValues(alpha: 0.1),
          ),
        Expanded(child: enableSlide ? slideList() : buildList()),
      ],
    );
    if (!_isSidePanel) {
      return ColoredBox(color: colorScheme.surface, child: child);
    }
    return child;
  }

  @override
  Widget buildList() {
    if (_hasSections) {
      return TabBarView(
        controller: _tabController,
        physics: tabBarScrollPhysics,
        horizontalDragGestureRecognizer: horizontalDragGestureRecognizer,
        children: activeTabChildren(
          _sections
              .mapIndexed((i, e) => _buildBody(e.episodes!, tabIndex: i))
              .toList(),
          controller: _tabController,
        ),
      );
    }
    return _buildBody(_episodes, tabIndex: _tabIndex());
  }

  Widget _buildBody(List<ugc.BaseEpisodeItem> episodes, {int tabIndex = 0}) {
    final isCurrTab = tabIndex == _tabIndex();

    Widget child;
    child = SliverVariedExtentList.builder(
      itemCount: episodes.length,
      itemBuilder: (context, index) {
        final episode = episodes[index];
        final isCurrItem = isCurrTab && index == _itemIndex();
        Widget episodeItem = _buildEpisodeItem(
          episode: episode,
          tabIndex: tabIndex,
          index: index,
          length: episodes.length,
          isCurrItem: isCurrItem,
        );
        if (episode is ugc.EpisodeItem && episode.pages!.length > 1) {
          return Column(
            mainAxisSize: .min,
            crossAxisAlignment: .start,
            children: [
              episodeItem, // 110
              Padding(
                padding: const .symmetric(horizontal: 12, vertical: 5), // 10
                child: PagePanel(
                  // 45
                  onBack: _isSidePanel ? null : _pop,
                  parts: isCurrItem ? null : episode.pages,
                  cover: episode.arc?.pic,
                  bvid: episode.bvid ?? IdUtils.av2bv(episode.aid!),
                  ugcIntroController: _ugcController,
                ),
              ),
            ],
          );
        }
        return episodeItem;
      },
      itemExtentBuilder: (index, _) => calcItemHeight(episodes[index]),
    );

    child = CustomScrollView(
      controller: _scrollController,
      reverse: _isReversed(tabIndex),
      physics: const AlwaysScrollableScrollPhysics(),
      slivers: [
        SliverPadding(
          padding: EdgeInsets.only(
            top: 7,
            bottom: MediaQuery.viewPaddingOf(context).bottom + 100,
          ),
          sliver: child,
        ),
      ],
    );

    if (_hasSections) {
      return KeepAliveWrapper(
        onBuild: () => setPosIndex(tabIndex),
        child: child,
      );
    } else {
      return child;
    }
  }

  late final _isVip = Accounts.isVideoVip;
  void _onChangeEpisode(
    int tabIndex,
    int index,
    ugc.BaseEpisodeItem episode,
    String title,
  ) {
    if (!_popIfNeeded()) {
      _lastTabIndex = tabIndex;
      _lastItemIndex = index;
    }

    if (episode.badge == "会员" && !_isVip) {
      SmartDialog.showToast('需要大会员');
      // return;
    }

    if (_isUgc) {
      _ugcController.onChangeEpisode(episode);
    } else {
      _pgcController.onChangeEpisode(
        episode,
        episodeType: _isSidePanel ? .episode : _episodeType,
      );
    }
  }

  Widget _buildEpisodeItem({
    required ugc.BaseEpisodeItem episode,
    required int tabIndex,
    required int index,
    required int length,
    required bool isCurrItem,
  }) {
    late String title;
    String? cover;
    String? bvid;
    num? duration;
    int? pubdate;
    int? view;
    int? danmaku;
    bool? isCharging;
    bool? cacheWidth;

    switch (episode) {
      case Part part:
        cover = part.firstFrame ?? _videoDetail.pic;
        title = part.part!;
        duration = part.duration;
        pubdate = part.ctime;
        cacheWidth = part.dimension?.cacheWidth;
        break;
      case ugc.EpisodeItem item:
        title = item.title!;
        bvid = item.bvid;
        if (item.arc case final arc?) {
          cover = arc.pic;
          duration = arc.duration;
          pubdate = arc.pubdate;
          if (arc.stat case final stat?) {
            view = stat.view;
            danmaku = stat.danmaku;
          }
          cacheWidth = arc.dimension?.cacheWidth;
        }
        if (item.attribute == 8) {
          isCharging = true;
        }
        break;
      case pgc.EpisodeItem item:
        bvid = item.bvid;
        title = item.showTitle ?? item.title!;
        cover = item.cover;
        if (item.from == 'pugv') {
          duration = item.duration;
          view = item.play;
        } else {
          duration = item.duration == null ? null : item.duration! ~/ 1000;
        }
        pubdate = item.pubTime;
        cacheWidth = item.dimension?.cacheWidth;
        break;
    }
    late final Color primary = colorScheme.primary;

    void onLongPress() {
      if (cover?.isNotEmpty == true) {
        imageSaveDialog(title: title, cover: cover, bvid: bvid);
      }
    }

    return Padding(
      padding: const .only(bottom: 2),
      child: SizedBox(
        height: 110,
        child: Material(
          type: .transparency,
          child: InkWell(
            onTap: () {
              if (isCurrItem) return;
              EasyDebounce.debounce(
                'onChangeEpisode',
                const Duration(milliseconds: 200),
                () => _onChangeEpisode(tabIndex, index, episode, title),
              );
            },
            onLongPress: onLongPress,
            onSecondaryTap: PlatformUtils.isMobile ? null : onLongPress,
            child: Padding(
              padding: const .symmetric(
                horizontal: Style.safeSpace,
                vertical: 5,
              ),
              child: Row(
                spacing: 10,
                children: [
                  if (cover?.isNotEmpty == true)
                    Stack(
                      clipBehavior: .none,
                      children: [
                        NetworkImgLayer(
                          src: cover,
                          width: 160,
                          height: 100,
                          cacheWidth: cacheWidth,
                        ),
                        if (duration != null && duration > 0)
                          PBadge(
                            text: DurationUtils.formatDuration(duration),
                            right: 6.0,
                            bottom: 6.0,
                            type: .gray,
                          ),
                        if (_type == .part)
                          Positioned(
                            top: 0,
                            right: 0,
                            child: Container(
                              padding: const .symmetric(horizontal: 4),
                              decoration: BoxDecoration(
                                color: colorScheme.secondaryContainer,
                                borderRadius: const .only(
                                  bottomLeft: .circular(4),
                                  topRight: Style.imgRadius,
                                ),
                              ),
                              child: Text(
                                (index + 1).toString(),
                                style: TextStyle(
                                  fontSize: 12,
                                  color: colorScheme.onSecondaryContainer,
                                ),
                              ),
                            ),
                          )
                        else if (isCharging == true)
                          const PBadge(
                            text: '充电专属',
                            top: 6,
                            right: 6,
                            type: .error,
                          )
                        else if (episode.badge != null)
                          PBadge(
                            text: episode.badge,
                            top: 6,
                            right: 6,
                            type: episode.badgeType,
                          ),
                      ],
                    )
                  else if (isCurrItem)
                    Image.asset(
                      Assets.livingStatic,
                      color: primary,
                      height: 12,
                      cacheHeight: 12.cacheSize(context),
                    ),
                  Expanded(
                    child: Column(
                      mainAxisSize: .min,
                      crossAxisAlignment: .start,
                      children: [
                        Expanded(
                          child: Text(
                            title,
                            textAlign: .start,
                            style: TextStyle(
                              height: 1.42,
                              letterSpacing: 0.3,
                              fontWeight: isCurrItem ? .bold : null,
                              color: isCurrItem ? primary : null,
                            ),
                            maxLines: 2,
                            overflow: .ellipsis,
                          ),
                        ),
                        if (pubdate != null)
                          Text(
                            DateFormatUtils.format(pubdate),
                            maxLines: 1,
                            style: TextStyle(
                              fontSize: 12,
                              height: 1,
                              color: colorScheme.outline,
                              overflow: .clip,
                            ),
                          ),
                        if (view != null) ...[
                          const SizedBox(height: 2),
                          Row(
                            spacing: 8,
                            children: [
                              StatWidget(
                                value: view,
                                type: .play,
                              ),
                              if (danmaku != null)
                                StatWidget(
                                  value: danmaku,
                                  type: .danmaku,
                                ),
                            ],
                          ),
                        ],
                      ],
                    ),
                  ),
                ],
              ),
            ),
          ),
        ),
      ),
    );
  }

  Future<void> _onFavSeason(bool isFav) async {
    final res = await FavHttp.seasonFav(
      isFav: isFav,
      seasonId: _seasonId,
    );
    if (res.isSuccess) {
      _favState!.toggle();
      _ugcController.seasonFavState[_seasonId] = !isFav;
      SmartDialog.showToast('${isFav ? '取消' : ''}订阅成功');
    } else {
      res.toast();
    }
  }

  Widget _buildFavBtn(bool? isFav) {
    if (isFav == null) return const SizedBox.shrink();
    return iconButton(
      iconSize: 22,
      tooltip: isFav ? '取消订阅' : '订阅',
      icon: isFav
          ? const Icon(Icons.notifications_off_outlined)
          : const Icon(Icons.notifications_active_outlined),
      onPressed: () => _onFavSeason(isFav),
    );
  }

  Widget get _buildDataReverseBtn => Obx(() {
    final tabIndex = _rxTabIndex.value;
    if (tabIndex != _tabIndex()) return const SizedBox.shrink();
    final isReversed = switch (_type) {
      .part => _videoDetail.isPageReversed,
      .season => _sections[tabIndex].isReversed,
      .pgc => throw UnimplementedError(),
    };
    return iconButton(
      iconSize: 22,
      tooltip: isReversed ? '正序播放' : '倒序播放',
      icon: isReversed
          ? const Icon(MdiIcons.sortDescending)
          : const Icon(MdiIcons.sortAscending),
      onPressed: () => {_popIfNeeded(), widget.onReverse!()},
    );
  });

  Widget get _buildUiReverseBtn => Obx(
    () {
      final tabIndex = _rxTabIndex.value;
      final reversed = _isReversed(tabIndex);
      return iconButton(
        iconSize: 22,
        tooltip: reversed ? '顺序' : '倒序',
        icon: reversed
            ? const Icon(MdiIcons.sortNumericDescending)
            : const Icon(MdiIcons.sortNumericAscending),
        onPressed: () => setState(() => _setReverse(tabIndex, !reversed)),
      );
    },
  );

  Widget _buildToolbar() => Container(
    height: 45,
    padding: .symmetric(horizontal: !_isSidePanel ? 14 : 6),
    decoration: BoxDecoration(
      border: Border(
        bottom: BorderSide(color: colorScheme.outline.withValues(alpha: 0.1)),
      ),
    ),
    child: Row(
      children: [
        if (!_isSidePanel)
          Text(
            _type.title,
            style: const TextStyle(fontSize: 16),
          ),
        if (_favState != null) Obx(() => _buildFavBtn(_favState!.value)),
        iconButton(
          iconSize: 22,
          tooltip: '跳至顶部',
          icon: const Icon(Icons.vertical_align_top),
          onPressed: _jumpToTop,
        ),
        iconButton(
          iconSize: 22,
          tooltip: '跳至底部',
          icon: const Icon(Icons.vertical_align_bottom),
          onPressed: _jumpToBottom,
        ),
        iconButton(
          iconSize: 22,
          tooltip: '跳至当前',
          icon: const Icon(Icons.my_location),
          onPressed: _jumpToCurrent,
        ),
        if (_isUgc) _buildDataReverseBtn,
        const Spacer(),
        _buildUiReverseBtn,
        if (!_isSidePanel)
          iconButton(
            iconSize: 22,
            tooltip: '关闭',
            icon: const Icon(Icons.close),
            onPressed: Get.back,
          ),
      ],
    ),
  );
}

