class MemberContribute extends StatefulWidget {
  const MemberContribute({
    super.key,
    this.heroTag,
    this.initialIndex,
    required this.mid,
  });

  final String? heroTag;
  final int? initialIndex;
  final int mid;

  @override
  State<MemberContribute> createState() => _MemberContributeState();
}

class _MemberContributeState extends State<MemberContribute>
    with AutomaticKeepAliveClientMixin {
  @override
  bool get wantKeepAlive => true;

  late final MemberContributeCtr _controller;

  @override
  void initState() {
    super.initState();
    _controller = Get.putOrFind(
      () => MemberContributeCtr(
        heroTag: widget.heroTag,
        initialIndex: widget.initialIndex,
      ),
      tag: widget.heroTag,
    );
  }

  @override
  Widget build(BuildContext context) {
    super.build(context);
    final theme = Theme.of(context);
    return _controller.tabs != null
        ? Column(
            crossAxisAlignment: .stretch,
            children: [
              HitTestWidget(
                child: TabBar(
                  overlayColor: const WidgetStatePropertyAll(
                    Colors.transparent,
                  ),
                  splashFactory: NoSplash.splashFactory,
                  padding: const .symmetric(horizontal: 8),
                  isScrollable: true,
                  tabs: _controller.tabs!,
                  tabAlignment: .start,
                  controller: _controller.tabController,
                  dividerHeight: 0,
                  indicatorWeight: 0,
                  indicatorPadding: const .symmetric(
                    horizontal: 3,
                    vertical: 8,
                  ),
                  indicator: BoxDecoration(
                    color: theme.colorScheme.secondaryContainer,
                    borderRadius: const BorderRadius.all(Radius.circular(20)),
                  ),
                  indicatorSize: .tab,
                  labelStyle:
                      TabBarTheme.of(
                        context,
                      ).labelStyle?.copyWith(fontSize: 14) ??
                      const TextStyle(fontSize: 14),
                  labelColor: theme.colorScheme.onSecondaryContainer,
                  unselectedLabelColor: theme.colorScheme.outline,
                ),
              ),
              Expanded(
                child: TabBarView(
                  physics: const NeverScrollableScrollPhysics(),
                  controller: _controller.tabController,
                  children: activeTabChildren(
                    _controller.items!.map(_getPageFromType).toList(),
                    controller: _controller.tabController,
                  ),
                ),
              ),
            ],
          )
        : _controller.items?.isNotEmpty == true
        ? _getPageFromType(_controller.items!.first)
        : scrollableError;
  }

  Widget _getPageFromType(SpaceTab2Item item) {
    final isSingle = _controller.tabs == null;
    return switch (item.param) {
      'video' => MemberVideo(
        type: ContributeType.video,
        heroTag: widget.heroTag,
        mid: widget.mid,
        title: item.title,
        isSingle: isSingle,
      ),
      'charging_video' => MemberVideo(
        type: ContributeType.charging,
        heroTag: widget.heroTag,
        mid: widget.mid,
        title: item.title,
      ),
      'article' => MemberArticle(
        heroTag: widget.heroTag,
        mid: widget.mid,
      ),
      'opus' => MemberOpus(
        heroTag: widget.heroTag,
        mid: widget.mid,
        isSingle: isSingle,
      ),
      'audio' => MemberAudio(
        heroTag: widget.heroTag,
        mid: widget.mid,
      ),
      'comic' => MemberComic(
        heroTag: widget.heroTag,
        mid: widget.mid,
      ),
      'season_video' => MemberVideo(
        type: ContributeType.season,
        heroTag: widget.heroTag,
        mid: widget.mid,
        seasonId: item.seasonId,
        title: item.title,
      ),
      'series' => MemberVideo(
        type: ContributeType.series,
        heroTag: widget.heroTag,
        mid: widget.mid,
        seriesId: item.seriesId,
        title: item.title,
      ),
      'ugcSeason' => SeasonSeriesPage(
        mid: widget.mid,
        heroTag: widget.heroTag,
      ),
      _ => Center(child: Text(item.title!)),
    };
  }
}

