  PlPlayerController._() {
    _danmakuStateSubscriptions.addAll([
      enableShowDanmaku.listen((_) => _notifyDanmakuState()),
      enableShowLiveDanmaku.listen((_) => _notifyDanmakuState()),
      danmakuOpacity.listen((_) => _notifyDanmakuState()),
      onlyPlayAudio.listen((_) {
        _notifyDanmakuState();
        _applyBackgroundVideoTrack();
      }),
    ]);
    if (PlatformUtils.isMobile && !DeviceUtils.isChromeOS) {
      _orientationListener = NativeDeviceOrientationPlatform.instance
          .onOrientationChanged(
            checkIsAutoRotate: checkIsAutoRotate,
            angleDegrees: Platform.isAndroid ? Pref.angleDegrees : null,
          )
          .listen(_onOrientationChanged);
    }

    if (!Accounts.heartbeat.isLogin || Pref.historyPause) {
      enableHeart = false;
    }

    if (Platform.isAndroid && autoPiP) {
      if (DeviceUtils.sdkInt < 31) {
        final func = Runnable.implement($Runnable(run: _onUserLeaveHint));
        AndroidHelper$ToDart.onUserLeaveHint = func;
        func.release();
      } else {
        _isAutoEnterPip = true;
      }
    } else if (Platform.isIOS && autoPiP && IOSPipHelper.isAvailable) {
      _isAutoEnterPip = true;
    }
  }

