    pp ??= _videoPlayerController!;
    switch (type) {
      case SuperResolutionType.disable:
        return pp.command(const ['change-list', 'glsl-shaders', 'clr', '']);
      case SuperResolutionType.efficiency:
        return pp.command([
          'change-list',
          'glsl-shaders',
          'set',
          PathUtils.buildShadersAbsolutePath(
            await copyShadersToExternalDirectory,
            Assets.mpvAnime4KShadersLite,
          ),
        ]);
      case SuperResolutionType.quality:
        return pp.command([
          'change-list',
          'glsl-shaders',
          'set',
          PathUtils.buildShadersAbsolutePath(
            await copyShadersToExternalDirectory,
            Assets.mpvAnime4KShaders,
          ),
        ]);
    }
  }

  Future<Player> _initPlayer() async {
    assert(_videoPlayerController == null);
    final opt = {
      'video-sync': Pref.videoSync,
      if (Platform.isAndroid) 'ao': Pref.audioOutput,
      'volume':
          (PlatformUtils.isMobile ? Pref.playerVolume : volume.value * 100)
              .toString(),
    };
    final autosync = Pref.autosync;
    if (autosync != '0') {
      opt['autosync'] = autosync;
    }

    final player = await Player.create(
      configuration: PlayerConfiguration(
        logLevel: kDebugMode ? .warn : .error,
        options: opt,
      ),
    );

    assert(_videoController == null);

    _videoController = await VideoController.create(
      player,
      configuration: VideoControllerConfiguration(
        enableHardwareAcceleration: hwdec != null,
        androidAttachSurfaceAfterVideoParameters: false,
        hwdec: hwdec,
      ),
    );

    if (Platform.isAndroid) {
      // Avoid sizing the surface using mpv's idle window between media loads.
      player.setProperty('force-window', 'no');
    }

    player.setMediaHeader(userAgent: BrowserUa.pc, referer: HttpString.baseUrl);

    _startListeners(player);

    return player;
  }

  late final buffer = Pref.initBuffer(_playbackSpeed.value);
  late final liveBuffer = Pref.initLiveBuffer();

  // 配置播放器
  Future<void> _createVideoController(
    DataSource dataSource,
    Duration? seekTo,
    Volume? volume,
    int? rotate,
  ) async {
    final generation = ++_transportGeneration;
    _backgroundVideoTrack.reset();
    _transportRecoveryTimer?.cancel();
    _transportRecoveryTimer = null;
    isBuffering.value = false;
    _heartDuration = 0;
    danmakuController?.clear();

    var player = _videoPlayerController;

    if (player == null) {
      player = await _initPlayer();
      if (_playerCount == 0) {
        _removeListeners();
        player.dispose();
        player = null;
        _videoController = null;
        return;
      }
      _videoPlayerController = player;
      if (isAnim && superResolutionType.value != .disable) {
        await setShader();
      }
    }

    final Map<String, String> extras = {
      if (dataSource is FileSource)
        'cache': 'no'
      else if (isLive)
        ...liveBuffer
      else
        ...buffer,
      'video-rotate': ?rotate?.toString(),
    };

    final oldTransport = _threadRipperTransport;
    ThreadRipperProxy? transport;
    String video = dataSource.videoSource;
    String? audio = dataSource.audioSource;
    final options = Pref.threadRipper;
    if (dataSource is NetworkSource &&
        options.enabled &&
        (!isLive || options.liveEnabled)) {
      try {
        final proxyPort = int.tryParse(Pref.systemProxyPort);
        transport = ThreadRipperProxy(
          options: options,
          concurrencyController: _threadRipperConcurrency,
          userAgent: BrowserUa.pc,
          referer: HttpString.baseUrl,
          onFallback: () {
            if (generation != _transportGeneration || _playerCount == 0) return;
            final resumePosition = _videoPlayerController?.state.position;
            final resumePlaying =
                _videoPlayerController?.state.playing == true ||
                playerStatus.isPlaying;
            _transportRecoveryTimer ??= Timer(
              const Duration(milliseconds: 300),
              () {
                _transportRecoveryTimer = null;
                if (generation != _transportGeneration ||
                    _playerCount == 0 ||
                    _processing) {
                  return;
                }
                if (_videoPlayerController case final player?
                    when player.current.isNotEmpty) {
                  final media = player.current.last.copyWith(
                    start: resumePosition ?? player.state.position,
                  );
                  _threadRipperRestarting = true;
                  unawaited(
                    _reloadPlaybackMedia(
                      player,
                      media,
                      play: resumePlaying,
                    ).catchError((Object _) {
                      SmartDialog.showToast('播放路线重载失败，请刷新视频');
                    }),
                  );
                }
              },
            );
          },
          upstreamProxy:
              Pref.enableSystemProxy &&
                  Pref.systemProxyHost.isNotEmpty &&
                  proxyPort != null
              ? 'PROXY ${Pref.systemProxyHost}:$proxyPort'
              : null,
        );
        await transport.start();
        if (generation != _transportGeneration || _playerCount == 0) {
          await transport.dispose();
          return;
        }
        video = isLive
            ? transport.wrapMedia(
                video,
                alternatives: dataSource.videoUrls,
                live: true,
              )
            : transport.wrapSource(video, alternatives: dataSource.videoUrls);
        if (!isLive && audio != null && audio.isNotEmpty) {
          audio = transport.wrapMedia(
            audio,
            alternatives: dataSource.audioUrls,
            rewriteCdn: !Pref.disableAudioCDN,
            isAudio: true,
          );
        }
      } catch (_) {
        await transport?.dispose();
        transport = null;
        video = dataSource.videoSource;
        audio = dataSource.audioSource;
        SmartDialog.showToast('多线程加速暂不可用，已使用原始播放路线');
      }
    }
    if (audio != null && audio.isNotEmpty) {
      if (onlyPlayAudio.value) {
        video = audio;
      } else {
        // dely_open need provide length
        video =
            ('edl://'
            '!no_chapters;'
            // '!delay_open,media_type=video;'
            '%${isFileSource ? utf8.encode(video).length : video.length}%$video;'
            '!new_stream;!no_chapters;'
            // '!delay_open,media_type=audio;'
            '%${isFileSource ? utf8.encode(audio).length : audio.length}%$audio');
      }
      audioFilterExtras(volume, map: extras);
    }

    assert(!isLive || seekTo == null);
    _threadRipperRestarting = true;
    try {
      await player.open(
        Media(
          video,
          start: seekTo,
          extras: extras.isEmpty ? null : extras,
        ),
        play: false,
      );
      if (generation != _transportGeneration || _playerCount == 0) {
        await transport?.dispose();
        return;
      }
      _threadRipperTransport = transport;
      _backgroundVideoTrack.sourceReady(
        generation,
        // Discover the selected audio first: deselecting the only video track
        // of a silent file makes mpv finish playback instead of saving energy.
        openedSuspended: false,
      );
      _applyBackgroundVideoTrack();
    } catch (_) {
      await transport?.dispose();
      if (generation == _transportGeneration &&
          identical(_threadRipperTransport, oldTransport)) {
        _threadRipperTransport = null;
      }
      rethrow;
    } finally {
      if (oldTransport != _threadRipperTransport) await oldTransport?.dispose();
    }
  }

  Future<void>? refreshPlayer() {
    if (dataSource is FileSource) {
      return null;
    }
    if (_videoPlayerController case final ctr? when (ctr.current.isNotEmpty)) {
      var media = ctr.current.last;
      if (!isLive) media = media.copyWith(start: ctr.state.position);
      _threadRipperRestarting = true;
      return _reloadPlaybackMedia(ctr, media, play: true);
    }
    return null;
  }

  // 开始播放
  Future<void> _initializePlayer() async {
    if (_instance == null) return;
    // 设置倍速
    if (_videoPlayerController != null) {
      final speed = isLive ? 1.0 : playbackSpeed;
      if (_videoPlayerController!.state.rate != speed) {
        await setPlaybackSpeed(speed);
      }
    }
    _initVideoFit();

    // 自动播放
    if (_autoPlay) {
      playIfExists();
    }
  }

  List<StreamSubscription>? _subscriptions;
  final Set<ValueChanged<Duration>> _positionListeners = {};
  final Set<ValueChanged<PlayerStatus>> _statusListeners = {};

  late final _wakeLockRelease = PlaybackWakeLockRelease(_stopWakeLock);

  void _startWakeLockTimer() {
    _wakeLockRelease.schedule();
  }

  void _stopWakeLockTimer() {
    _wakeLockRelease.cancel();
  }

  void _stopWakeLock() {
    WakelockPlus.disable();
    _updatePlaybackState(debugLabel: 'onVideoPaused');
  }

  void _updatePlaybackState({Duration? position, String? debugLabel}) {
    videoPlayerServiceHandler?.onUpdateState(
      playerStatus,
      isBuffering.value,
      isLive,
      position: position ?? _videoPlayerController!.state.position,
      speed: playbackSpeed,
      debugLabel: debugLabel,
    );
    _updateIOSPip(position);
  }

  /// 播放事件监听
  void _startListeners(NativePlayer player) {
    assert(_subscriptions == null);
    final stream = player.stream;
    _subscriptions = [
      /// playing
      stream.playing.listen((bool playing) {
        if (playing) {
          playerStatus = .playing;
          _stopWakeLockTimer();
          _updatePlaybackState();
          WakelockPlus.enable();

          if (_isAutoEnterPip) {
            if (_isCurrVideoPage) {
              enterPip(autoEnter: true);
            } else {
              _disableAutoEnterPip();
            }
          }
        } else {
          playerStatus = .paused;
          _startWakeLockTimer();
          _disableAutoEnterPip();
          _updateIOSPip();
        }

        for (final element in _statusListeners) {
          element(playing ? .playing : .paused);
        }

        final seconds = videoPlayerController!.state.position.inSeconds;
        if (seconds != 0) {
          makeHeartBeat(seconds, type: .status);
        }
      }),

      ///completed
      stream.completed.listen((bool completed) {
        if (completed) {
          playerStatus = .completed;
          _startWakeLockTimer();

          for (final element in _statusListeners) {
            element(.completed);
          }

          makeHeartBeat(-1, type: .completed);
        }
      }),

      /// position
      stream.position.listen((Duration position) {
        _threadRipperTransport?.concurrencyController.buffer(
          (player.state.buffer - position).inMilliseconds / 1000,
          player.state.playing && !_threadRipperRestarting,
        );
        final posInSeconds = position.inSeconds;

        if (posInSeconds != this.position.value) {
          if (posInSeconds == 0 && playerStatus.isPlaying) {
            _updatePlaybackState(position: position);
          }

          this.position.value = posInSeconds;

          makeHeartBeat(posInSeconds);
        }

        for (final element in _positionListeners) {
          element(position);
        }
      }),
      stream.duration.listen((Duration duration) {
        updateDuration(duration);
        _updateIOSPip();
      }),
      stream.tracks.listen((_) => _applyBackgroundVideoTrack()),
      stream.audioParams.listen((_) => _applyBackgroundVideoTrack()),
      stream.buffer.listen((Duration buffer) {
        buffered.value = buffer.inSeconds;
      }),
      stream.buffering.listen((bool buffering) {
        if (buffering &&
            !isBuffering.value &&
            !_threadRipperRestarting &&
            player.state.playing &&
            player.state.position > Duration.zero) {
          _threadRipperTransport?.concurrencyController.stall();
        }
        if (!buffering) _threadRipperRestarting = false;
        isBuffering.value = buffering;
        if (!playerStatus.isCompleted) {
          _wakeLockRelease.buffering(playing: playerStatus.isPlaying);
          _updatePlaybackState();
        }
      }),
      if (kDebugMode)
        stream.log.listen(((PlayerLog log) {
          if (log.level == 'error' || log.level == 'fatal') {
            Utils.reportError(
              '${log.level}: ${log.prefix}: ${log.text}\n${player.state.playlist}',
              null,
            );
          } else {
            debugPrint(log.toString());
          }
        })),
      stream.error.listen((String event) {
        if (dataSource is FileSource &&
            event.startsWith("Failed to open file")) {
          return;
        }
        final generation = _transportGeneration;
        final loopbackFailure =
            event.startsWith('Failed to open http://127.0.0.1:') ||
            event.startsWith('Can not open external file http://127.0.0.1:');
        if (isLive) {
          if (event.startsWith('tcp: ffurl_read returned ') ||
              event.startsWith("Failed to open https://") ||
              event.startsWith("Can not open external file https://") ||
              loopbackFailure) {
            Timer(const Duration(milliseconds: 3000), () {
              if (generation == _transportGeneration &&
                  _playerCount != 0 &&
                  !_processing) {
                refreshPlayer();
              }
            });
          }
          return;
        }
        if (event.startsWith("Failed to open https://") ||
            event.startsWith("Can not open external file https://") ||
            loopbackFailure ||
            //tcp: ffurl_read returned 0xdfb9b0bb
            //tcp: ffurl_read returned 0xffffff99
            event.startsWith('tcp: ffurl_read returned ')) {
          EasyThrottle.throttle(
            'controllerStream.error.listen',
            const Duration(milliseconds: 10000),
            () => Timer(const Duration(milliseconds: 3000), () {
              if (generation != _transportGeneration ||
                  _playerCount == 0 ||
                  _processing) {
                return;
              }
              // if (kDebugMode) {
              //   debugPrint("isBuffering.value: ${isBuffering.value}");
              // }
              // if (kDebugMode) {
              //   debugPrint("_buffered.value: ${_buffered.value}");
              // }
              if (isBuffering.value && buffered.value == 0) {
                SmartDialog.showToast(
                  '视频链接打开失败，重试中',
                  displayTime: const Duration(milliseconds: 500),
                );
                refreshPlayer();
              }
            }),
          );
        } else if (event.startsWith('Could not open codec')) {
          SmartDialog.showToast('无法加载解码器, $event，可能会切换至软解');
        } else if (!onlyPlayAudio.value) {
          if (event.startsWith("error running") ||
              event.startsWith("Failed to open .") ||
              event.startsWith("Cannot open") ||
              event.startsWith("Can not open")) {
            return;
          }
          if (!kDebugMode) {
            Utils.reportError('$event\n${player.state.playlist}');
          }
          // SmartDialog.showToast('视频加载错误, $event');
        }
      }),
    ];
  }

  /// 移除事件监听
  void _removeListeners() {
    _subscriptions?.forEach((e) => e.cancel());
    _subscriptions?.clear();
    _subscriptions = null;
  }

  void _cancelSubForSeek() {
    if (_subForSeek != null) {
      _subForSeek!.cancel();
      _subForSeek = null;
    }
  }

  Future<void> seek(Duration position, {bool isSeek = false}) async {
    if (isSeek) {
      /// 拖动进度条调节时，不等待第一帧，防止抖动
      await _videoPlayerController?.stream.buffer.first;
    }
    danmakuController?.clear();
    try {
      _threadRipperRestarting = true;
      await _videoPlayerController?.seek(position);
      _updateIOSPip(position);
    } catch (e) {
      if (kDebugMode) debugPrint('seek failed: $e');
    }
  }

  /// 跳转至指定位置
  Future<void> seekTo(Duration position, {bool isSeek = true}) async {
    if (_playerCount == 0) {
      return;
    }
    if (position < Duration.zero) {
      position = Duration.zero;
    }
    _heartDuration = position.inSeconds;

    if (duration.value != 0) {
      seek(position, isSeek: isSeek);
    } else {
      // if (kDebugMode) debugPrint('seek duration else');
      _subForSeek?.cancel();
      _subForSeek = duration.listen((_) {
        seek(position, isSeek: isSeek);
        _cancelSubForSeek();
      });
    }
  }

  /// 设置倍速
  Future<void> setPlaybackSpeed(double speed) async {
    lastPlaybackSpeed = playbackSpeed;

    if (speed == _videoPlayerController?.state.rate) return;

    await _videoPlayerController?.setRate(speed);
    if (!isLive) _playbackSpeed.value = speed;
    _updatePlaybackState();
    if (danmakuController != null) {
      try {
        danmakuController?.updateOption(
          danmakuController!.option.copyWith(
            duration: DanmakuOptions.danmakuDuration / speed,
            staticDuration: DanmakuOptions.danmakuStaticDuration / speed,
          ),
        );
      } catch (_) {}
    }
  }

  /// 播放视频
  Future<void> play({bool repeat = false, bool hideControls = true}) async {
    if (_playerCount == 0) return;
    // 播放时自动隐藏控制条
    controls = !hideControls;
    // repeat为true，将从头播放
    if (repeat) {
      await seekTo(Duration.zero, isSeek: false);
    }

    await _videoPlayerController?.play();

    audioSessionHandler?.setActive(true);

    playerStatus = .playing;
  }

  /// 暂停播放
  Future<void> pause({bool notify = true, bool isInterrupt = false}) async {
    await _videoPlayerController?.pause();
    playerStatus = .paused;

    // 主动暂停时让出音频焦点
    if (!isInterrupt) {
      audioSessionHandler?.setActive(false);
    }
  }

  bool tripling = false;

  /// 隐藏控制条
  void hideTaskControls() {
    _timer?.cancel();
    _timer = Timer(showControlDuration, () {
      if (!isSeeking.value && !tripling && hoverDx == null) {
        controls = false;
      }
      _timer = null;
    });
  }

