              () => _BorderIndicator(
                radius: const Radius.circular(20),
                isLeft: _liveRoomController.pageIndex.value == 0,
              ),
            ),
          ),
        ],
      );
    }
    return child;
  }

  WidgetStateProperty<Color?>? _overlayColor(ColorScheme colorScheme) =>
      WidgetStateProperty.resolveWith((Set<WidgetState> states) {
        final color = states.contains(WidgetState.selected)
            ? colorScheme.primary
            : colorScheme.onSurfaceVariant;
        if (states.contains(WidgetState.pressed)) {
          return color.withValues(alpha: 0.1);
        } else if (states.contains(WidgetState.hovered)) {
          return color.withValues(alpha: 0.08);
        } else if (states.contains(WidgetState.focused)) {
          return color.withValues(alpha: 0.1);
        } else {
          return Colors.transparent;
        }
      });
}

class _BorderIndicator extends LeafRenderObjectWidget {
  const _BorderIndicator({
    required this.radius,
    required this.isLeft,
  });

  final Radius radius;
  final bool isLeft;

  @override
  RenderObject createRenderObject(BuildContext context) {
    return _RenderBorderIndicator(
      radius: radius,
      isLeft: isLeft,
    );
  }

  @override
  void updateRenderObject(
    BuildContext context,
    _RenderBorderIndicator renderObject,
  ) {
    renderObject
      ..radius = radius
      ..isLeft = isLeft;
  }
}

class _RenderBorderIndicator extends RenderBox {
  _RenderBorderIndicator({
    required this._radius,
    required this._isLeft,
  });

  Radius _radius;
  Radius get radius => _radius;
  set radius(Radius value) {
    if (_radius == value) return;
    _radius = value;
    markNeedsLayout();
  }

  bool _isLeft;
  bool get isLeft => _isLeft;
  set isLeft(bool value) {
    if (_isLeft == value) return;
    _isLeft = value;
    markNeedsPaint();
  }

  @override
  void performLayout() {
    size = constraints.constrainDimensions(constraints.maxWidth, _radius.x);
  }

  @override
  void paint(PaintingContext context, Offset offset) {
    final size = this.size;
    final canvas = context.canvas;
    final width = size.width / 2;

    BoxBorder.paintNonUniformBorder(
      canvas,
      Rect.fromLTWH(
        offset.dx + (_isLeft ? 0 : width),
        offset.dy,
        width,
        size.height,
      ),
      borderRadius: BorderRadius.only(
        topLeft: _isLeft ? _radius : .zero,
        topRight: _isLeft ? .zero : _radius,
      ),
      textDirection: null,
      top: const BorderSide(),
      color: Colors.white38,
    );
  }
}

class LiveDanmaku extends StatefulWidget {
  final LiveRoomController liveRoomController;
  final PlPlayerController plPlayerController;
  final bool isPipMode;
  final bool isFullScreen;
  final Size size;

  const LiveDanmaku({
    super.key,
    required this.liveRoomController,
    required this.plPlayerController,
    this.isPipMode = false,
    required this.isFullScreen,
    required this.size,
  });

  @override
  State<LiveDanmaku> createState() => _LiveDanmakuState();

  bool get notFullscreen => !isFullScreen || isPipMode;
}

class _LiveDanmakuState extends State<LiveDanmaku> {
  PlPlayerController get plPlayerController => widget.plPlayerController;
  DanmakuController<DanmakuExtra>? _controller;

  bool get _visible =>
      widget.liveRoomController.routeVisible.value &&
      plPlayerController.shouldRenderDanmaku(
        enabled: plPlayerController.enableShowLiveDanmaku.value,
        inPip: widget.isPipMode,
        requirePlaying: false,
      );

  void _onStateChanged() {
    // Backgrounded apps may not render another frame. Stop the actual canvas
    // immediately rather than waiting for a later opacity/widget update.
    if (!_visible) {
      _controller
        ?..pause()
        ..clear();
    } else if (!plPlayerController.playerStatus.isPlaying) {
      _controller?.pause();
    } else {
      _controller?.resume();
    }
    if (mounted) setState(() {});
  }

  void _onPlayerStatus(PlayerStatus _) => _onStateChanged();

  @override
  void initState() {
    super.initState();
    plPlayerController
      ..addDanmakuStateListener(_onStateChanged)
      ..addStatusLister(_onPlayerStatus);
  }

  @override
  void didUpdateWidget(LiveDanmaku oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (oldWidget.plPlayerController != plPlayerController) {
      oldWidget.plPlayerController
        ..removeDanmakuStateListener(_onStateChanged)
        ..removeStatusLister(_onPlayerStatus);
      plPlayerController
        ..addDanmakuStateListener(_onStateChanged)
        ..addStatusLister(_onPlayerStatus);
    }
  }

  @override
  void dispose() {
    plPlayerController
      ..removeDanmakuStateListener(_onStateChanged)
      ..removeStatusLister(_onPlayerStatus);
    if (identical(widget.liveRoomController.danmakuController, _controller)) {
      widget.liveRoomController.danmakuController = null;
    }
    if (identical(plPlayerController.danmakuController, _controller)) {
      plPlayerController.danmakuController = null;
    }
    super.dispose();
  }

  @override
  Widget build(BuildContext context) {
    final option = DanmakuOptions.get(notFullscreen: widget.notFullscreen);
    return Obx(
      () => EnergyAwareDanmaku<DanmakuExtra>(
        enabled: _visible,
        playing: plPlayerController.playerStatus.isPlaying,
        opacity: plPlayerController.danmakuOpacity.value,
        createdController: (controller) {
          _controller = controller;
          widget.liveRoomController.danmakuController =
              plPlayerController.danmakuController = controller;
        },
        option: option,
        size: widget.size,
      ),
    );
  }
}

