import 'package:PiliPlus/utils/desktop/playback_visibility.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  test('duplicate hide events preserve one resume and later restores stay idle',
      () {
    var playing = true;
    final events = <String>[];
    final policy = WindowPlaybackVisibility(
      isEnabled: () => true,
      isPlaying: () => playing,
      pause: () {
        playing = false;
        events.add('pause');
      },
      play: () {
        playing = true;
        events.add('play');
      },
    );
    policy.hide();
    policy.hide();
    policy.show();
    expect(events, ['pause', 'play']);
    playing = false;
    policy.show();
    expect(events, ['pause', 'play']);
  });

  test('an already paused player is never resumed by the window', () {
    final events = <String>[];
    final policy = WindowPlaybackVisibility(
      isEnabled: () => true,
      isPlaying: () => false,
      pause: () => events.add('pause'),
      play: () => events.add('play'),
    );
    policy.hide();
    policy.show();
    expect(events, isEmpty);
  });

  test('turning off pause-on-minimize consumes the pending resume', () {
    var enabled = true;
    var playing = true;
    final events = <String>[];
    final policy = WindowPlaybackVisibility(
      isEnabled: () => enabled,
      isPlaying: () => playing,
      pause: () {
        playing = false;
        events.add('pause');
      },
      play: () => events.add('play'),
    );
    policy.hide();
    enabled = false;
    policy.show();
    enabled = true;
    policy.show();
    expect(events, ['pause']);
  });

  test('disabled window playback handling leaves playback alone', () {
    final events = <String>[];
    final policy = WindowPlaybackVisibility(
      isEnabled: () => false,
      isPlaying: () => true,
      pause: () => events.add('pause'),
      play: () => events.add('play'),
    );
    policy.hide();
    policy.show();
    expect(events, isEmpty);
  });
}
